std::string lower(std::string s) {
    for (char& c : s)
        if (c >= 'A' && c <= 'Z') c = static_cast<char>(c - 'A' + 'a');
    return s;
}

bool contains(const std::vector<std::string>& v, const std::string& s) {
    return std::find(v.begin(), v.end(), s) != v.end();
}

bool strictInt(const std::string& s, int& out) {
    if (s.empty() || s.size() > 9) return false;
    std::size_t i = 0;
    bool neg = false;
    if (s[0] == '-') { neg = true; i = 1; }
    if (i >= s.size()) return false;
    long v = 0;
    for (; i < s.size(); ++i) {
        if (s[i] < '0' || s[i] > '9') return false;
        v = v * 10 + (s[i] - '0');
    }
    out = static_cast<int>(neg ? -v : v);
    return true;
}

bool isBlankChar(char c) { return (c >= 'a' && c <= 'z') || c == '_'; }

// If a well-formed blank starts at i, returns its length (including braces), else 0.
std::size_t blankAt(const std::string& t, std::size_t i) {
    if (t[i] != '{') return 0;
    std::size_t j = i + 1;
    while (j < t.size() && isBlankChar(t[j])) ++j;
    if (j == i + 1 || j >= t.size() || t[j] != '}') return 0;
    return j - i + 1;
}

bool hasStage(const StringRow& r, int stage) { return r.stageOk && r.stageMin <= stage && stage <= r.stageMax; }

