const json::Value* need(const json::Value& o, const char* key, json::Type t, const std::string& ctx, Issue& err) {
    const json::Value* v = o.isObject() ? o.find(key) : nullptr;
    if (!v) { schema(err, ctx + ": missing \"" + key + "\""); return nullptr; }
    if (v->type != t) { schema(err, ctx + ": \"" + key + "\" has the wrong type"); return nullptr; }
    return v;
}

bool stringList(const json::Value& arr, const std::string& ctx, std::vector<std::string>& out, Issue& err) {
    out.clear();
    for (const json::Value& e : arr.items) {
        if (!e.isString()) return schema(err, ctx + ": expected strings");
        out.push_back(e.string);
    }
    return true;
}

void collectKeys(const json::Value& v, std::vector<std::string>& out) {
    if (v.isString()) {
        const std::string& s = v.string;
        bool pfx = s.compare(0, 4, "fig_") == 0 || s.compare(0, 5, "lift_") == 0 || s.compare(0, 4, "log_") == 0;
        bool word = !s.empty();
        for (char c : s)
            if (!(isBlankChar(c) || (c >= '0' && c <= '9'))) word = false;
        bool threshold = s.size() >= 9 && s.compare(s.size() - 9, 9, "threshold") == 0;
        if (pfx && word && !threshold) out.push_back(s);
    }
    for (const json::Value& c : v.items) collectKeys(c, out);
}

std::string esc(const std::string& s) {
    std::string r = "\"";
    for (char c : s) {
        unsigned char u = static_cast<unsigned char>(c);
        if (c == '"') r += "\\\"";
        else if (c == '\\') r += "\\\\";
        else if (u < 0x20) {
            char buf[8];
            std::snprintf(buf, sizeof buf, "\\u%04x", u);
            r += buf;
        } else r += c;
    }
    return r + "\"";
}

bool fillRec(const Strings& s, const std::string& key, int stage, const std::map<std::string, std::string>& values,
             std::string& out, Issue& err, int depth) {
    if (stage < -2 || stage > 2) { err.code = "STAGE_RANGE"; err.detail = std::to_string(stage); return false; }
    if (depth > 8) { err.code = "FILL_DEPTH"; err.detail = key; return false; }
    if (!s.find(key)) { err.code = "UNKNOWN_KEY"; err.detail = key; return false; }
    const StringRow* row = s.forStage(key, stage);
    if (!row) { err.code = "NO_LINE"; err.detail = key; return false; }
    const std::string& t = row->text;
    std::string r;
    for (std::size_t i = 0; i < t.size();) {
        std::size_t n = blankAt(t, i);
        if (n == 0) { r += t[i++]; continue; }
        std::string name = t.substr(i + 1, n - 2);
        std::map<std::string, std::string>::const_iterator it = values.find(name);
        if (it == values.end()) { err.code = "UNFILLED_BLANK"; err.detail = name; return false; }
        if (!it->second.empty() && it->second[0] == '@') {
            std::string inner;
            if (!fillRec(s, it->second.substr(1), stage, values, inner, err, depth + 1)) return false;
            r += inner;
        } else {
            r += it->second;
        }
        i += n;
    }
    out = r;
    return true;
}

