// ---- states and bands ------------------------------------------------------------------------
const char* stateName(State s) {
    switch (s) {
        case State::NotOffered: return "not_offered";
        case State::Declined: return "declined";
        case State::Active: return "active";
        case State::ObservedPresent: return "observed_present";
        case State::ObservedGone: return "observed_gone";
        case State::Completed: return "completed";
    }
    return "?";
}

bool stateFromName(const std::string& name, State& out) {
    static const State all[] = {State::NotOffered, State::Declined, State::Active,
                                State::ObservedPresent, State::ObservedGone, State::Completed};
    for (State s : all)
        if (name == stateName(s)) { out = s; return true; }
    return false;
}

bool stageFromScore(long long score, int& stage) {
    if (score < 0 || score > 100) return false;
    stage = score >= 80 ? 2 : score >= 60 ? 1 : score >= 40 ? 0 : score >= 20 ? -1 : -2;
    return true;
}

