// ---- quest data ----------------------------------------------------------------------------
bool QuestData::next(State from, const std::string& event, State& to) const {
    for (const Transition& t : transitions) {
        State f;
        if (stateFromName(t.from, f) && f == from && t.event == event && stateFromName(t.to, to)) return true;
    }
    return false;
}

bool load(const std::string& questJson, const std::string& stringsCsv, QuestData& out, Issue& err) {
    json::Value root;
    json::Error je;
    if (!json::parse(questJson, root, je)) {
        err.code = je.code;
        err.detail = je.describe();
        return false;
    }
    QuestData q;
    if (!loadStrings(stringsCsv, q.strings, err)) return false;
    if (!root.isObject()) return schema(err, "top level is not an object");
    const json::Value* v;
    if (!(v = need(root, "quest_id", json::Type::String, "quest", err))) return false;
    q.questId = v->string;

    if (!(v = need(root, "giver", json::Type::Object, "quest", err))) return false;
    const json::Value* a;
    if (!(a = need(*v, "node", json::Type::String, "giver", err))) return false;
    q.giverNode = a->string;
    if (!(a = need(*v, "npc", json::Type::String, "giver", err))) return false;
    q.giverNpc = a->string;

    if (!(v = need(root, "destination", json::Type::Object, "quest", err))) return false;
    if (!(a = need(*v, "node", json::Type::String, "destination", err))) return false;
    q.destNode = a->string;
    if (!(a = need(*v, "map_key", json::Type::String, "destination", err))) return false;
    q.destMapKey = a->string;

    if (!(v = need(root, "route", json::Type::Array, "quest", err))) return false;
    if (!stringList(*v, "route", q.route, err)) return false;
    if (!(v = need(root, "route_edges", json::Type::Array, "quest", err))) return false;
    if (!stringList(*v, "route_edges", q.routeEdges, err)) return false;

    if (!(v = need(root, "discovery", json::Type::Object, "quest", err))) return false;
    if (!(a = need(*v, "default_chain_state", json::Type::String, "discovery", err))) return false;
    q.chainDefault = a->string;
    if (!(a = need(*v, "chain_state_values", json::Type::Array, "discovery", err))) return false;
    if (!stringList(*a, "chain_state_values", q.chainValues, err)) return false;
    if (!contains(q.chainValues, q.chainDefault)) return schema(err, "discovery: default_chain_state is not a chain value");

    if (!(v = need(root, "blanks_allowed", json::Type::Array, "quest", err))) return false;
    {
        std::vector<std::string> raw;
        if (!stringList(*v, "blanks_allowed", raw, err)) return false;
        for (const std::string& b : raw) {
            if (b.size() < 3 || blankAt(b, 0) != b.size()) return schema(err, "blanks_allowed: bad blank " + b);
            q.blanksAllowed.push_back(b.substr(1, b.size() - 2));
        }
    }

    if (!(v = need(root, "states", json::Type::Array, "quest", err))) return false;
    if (!stringList(*v, "states", q.states, err)) return false;

    if (!(v = need(root, "transitions", json::Type::Array, "quest", err))) return false;
    for (const json::Value& t : v->items) {
        Transition tr;
        if (!(a = need(t, "from", json::Type::String, "transition", err))) return false;
        tr.from = a->string;
        if (!(a = need(t, "event", json::Type::String, "transition", err))) return false;
        tr.event = a->string;
        if (!(a = need(t, "to", json::Type::String, "transition", err))) return false;
        tr.to = a->string;
        q.transitions.push_back(tr);
    }

    if (!(v = need(root, "strings", json::Type::Object, "quest", err))) return false;
    for (std::size_t i = 0; i < v->items.size(); ++i) {
        const json::Value& g = v->items[i];
        if (!g.isArray()) return schema(err, "strings: group " + v->keys[i] + " is not an array");
        if (!stringList(g, "strings." + v->keys[i], q.stringGroups[v->keys[i]], err)) return false;
    }

    if (!(v = need(root, "report_variants", json::Type::Object, "quest", err))) return false;
    collectKeys(*v, q.reportVariantKeys);

    out = q;
    return true;
}

// ---- validation ------------------------------------------------------------------------------
std::vector<Issue> validate(const QuestData& q, const map::FloorMap& m) {
    std::vector<Issue> is;
    auto add = [&is](const std::string& code, const std::string& detail) {
        Issue i;
        i.code = code;
        i.detail = detail;
        is.push_back(i);
    };

    // 1. map IDs
    std::set<std::string> seen;
    std::vector<std::string> nodes;
    nodes.push_back(q.giverNode);
    nodes.push_back(q.destNode);
    for (const std::string& n : q.route) nodes.push_back(n);
    for (const std::string& n : nodes)
        if (!m.node(n) && seen.insert(n).second) add("UNKNOWN_NODE", n);
    bool edgesKnown = true;
    for (const std::string& e : q.routeEdges)
        if (!m.edge(e)) { add("UNKNOWN_EDGE", e); edgesKnown = false; }

    // 2. destination agrees with the map's quest_destinations
    {
        std::string key = q.destMapKey;
        std::size_t dot = key.rfind('.');
        if (dot != std::string::npos) key = key.substr(dot + 1);
        bool found = false, same = false;
        for (const map::QuestDestination& d : m.questDestinations)
            if (d.key == key) { found = true; same = d.node == q.destNode; }
        if (!found || !same) add("DEST_MISMATCH", q.destNode + " (map key " + key + ")");
    }

    // 3. route: ends, edges join consecutive nodes, every edge plain (the quest must need no pick or break)
    if (q.route.empty() || q.route.front() != q.giverNode || q.route.back() != q.destNode)
        add("ROUTE_ENDS", "route must run from the giver node to the destination node");
    if (edgesKnown) {
        if (q.routeEdges.size() + 1 != q.route.size()) {
            add("ROUTE_EDGE", "route has " + std::to_string(q.route.size()) + " nodes but " +
                                  std::to_string(q.routeEdges.size()) + " edges");
        } else {
            for (std::size_t i = 0; i < q.routeEdges.size(); ++i) {
                const map::Edge* e = m.edge(q.routeEdges[i]);
                const std::string& a = q.route[i];
                const std::string& b = q.route[i + 1];
                if (!((e->from == a && e->to == b) || (e->from == b && e->to == a)))
                    add("ROUTE_EDGE", q.routeEdges[i] + " does not join " + a + " and " + b);
            }
        }
        for (const std::string& id : q.routeEdges) {
            const map::Edge* e = m.edge(id);
            if (e->door != "plain") add("ROUTE_NOT_PLAIN", id + " is a " + e->door + " door");
        }
    }

    // 4. keys
    const std::vector<StringRow>& rows = q.strings.rows;
    std::set<std::string> csvKeys, dups;
    for (const StringRow& r : rows)
        if (!csvKeys.insert(r.key).second && dups.insert(r.key).second) add("DUP_KEY", r.key);
    std::set<std::string> jsonKeys;
    std::vector<std::string> jsonOrder;
    for (const auto& g : q.stringGroups)
        for (const std::string& k : g.second)
            if (jsonKeys.insert(k).second) jsonOrder.push_back(k);
    for (const std::string& k : jsonOrder)
        if (!csvKeys.count(k)) add("MISSING_KEY", k);
    for (const std::string& k : q.reportVariantKeys)
        if (!csvKeys.count(k) && !jsonKeys.count(k)) add("MISSING_KEY", k);
    std::set<std::string> orphans;
    for (const StringRow& r : rows)
        if (!jsonKeys.count(r.key) && orphans.insert(r.key).second) add("ORPHAN_KEY", r.key);

    // 5. stage coverage (before the range rule, so a min above max on a covered key reads as lost coverage)
    for (const char* k : kHostileKeys) {
        const StringRow* r = q.strings.find(k);
        if (r && r->stageOk && !(r->stageMin <= -2 && -2 <= r->stageMax)) add("STAGE_COVERAGE", k);
    }
    {
        const StringRow* r = q.strings.find(kRefusedKey);
        if (r && r->stageOk && !(r->stageMin == -2 && r->stageMax == -2)) add("STAGE_COVERAGE", kRefusedKey);
        std::map<std::string, std::vector<std::string> >::const_iterator g = q.stringGroups.find("offer");
        if (g != q.stringGroups.end())
            for (const std::string& k : g->second) {
                if (k == kRefusedKey) continue;
                for (const StringRow& row : rows)
                    if (row.key == k && row.stageOk && row.stageMin <= -2 && -2 <= row.stageMax) {
                        add("STAGE_COVERAGE", k + " (only " + kRefusedKey + " may offer at -2)");
                        break;
                    }
            }
    }

    // 6. stage range
    for (const StringRow& r : rows)
        if (!r.stageOk || !(-2 <= r.stageMin && r.stageMin <= r.stageMax && r.stageMax <= 2))
            add("STAGE_RANGE", r.key + " (" + r.stageMinText + ".." + r.stageMaxText + ")");

    // 7. overlap among alternatives for one moment: the offers, and the cold/warm report pairs
    {
        std::map<std::string, std::vector<std::string> > groups;
        std::map<std::string, std::vector<std::string> >::const_iterator og = q.stringGroups.find("offer");
        if (og != q.stringGroups.end()) groups["offer"] = og->second;
        std::map<std::string, std::vector<std::string> >::const_iterator rg = q.stringGroups.find("report");
        if (rg != q.stringGroups.end())
            for (const std::string& k : rg->second) {
                std::size_t n = k.size();
                if (n > 5 && k.compare(n - 5, 5, "_cold") == 0) groups[k.substr(0, n - 5)].push_back(k);
                else if (n > 5 && k.compare(n - 5, 5, "_warm") == 0) groups[k.substr(0, n - 5)].push_back(k);
            }
        for (const auto& g : groups) {
            std::vector<const StringRow*> rs;
            for (const std::string& k : g.second)
                for (const StringRow& r : rows)
                    if (r.key == k && r.stageOk) rs.push_back(&r);
            for (std::size_t i = 0; i < rs.size(); ++i)
                for (std::size_t j = i + 1; j < rs.size(); ++j)
                    if (rs[i]->key != rs[j]->key && rs[i]->stageMin <= rs[j]->stageMax && rs[j]->stageMin <= rs[i]->stageMax)
                        add("STAGE_OVERLAP", rs[i]->key + " and " + rs[j]->key);
        }
    }

    // 8. blanks
    for (const StringRow& r : rows) {
        bool stray = false;
        std::vector<std::string> found = blanksIn(r.text, &stray);
        bool bad = stray;
        std::string badName = stray ? "stray brace" : "";
        for (const std::string& b : found)
            if (!contains(q.blanksAllowed, b)) { bad = true; badName = "{" + b + "}"; break; }
        if (bad) add("BAD_BLANK", r.key + " " + badName);
        std::set<std::string> f(found.begin(), found.end()), d(r.blanks.begin(), r.blanks.end());
        if (f != d) add("BLANK_MISMATCH", r.key);
    }

    // 9. banned phrases: the Figure never states his reason
    for (const StringRow& r : rows) {
        std::string low = lower(r.text);
        for (const char* b : kBanned)
            if (low.find(b) != std::string::npos) { add("BANNED_PHRASE", r.key + " '" + b + "'"); break; }
    }

    // 10. transition table
    std::set<std::string> stateNames(q.states.begin(), q.states.end());
    for (const Transition& t : q.transitions) {
        State s1, s2;
        bool known = stateNames.count(t.from) && stateNames.count(t.to) && stateFromName(t.from, s1) && stateFromName(t.to, s2);
        if (!known) add("BAD_TRANSITION", t.from + " --" + t.event + "--> " + t.to);
    }
    struct Probe { State from; const char* event; State to; };
    const Probe probes[] = {
        {State::NotOffered, "accept", State::Active},
        {State::NotOffered, "decline", State::Declined},
        {State::Declined, "accept", State::Active},
        {State::Active, "arrive_ore_lift_chain_present", State::ObservedPresent},
        {State::Active, "arrive_ore_lift_chain_gone", State::ObservedGone},
        {State::ObservedPresent, "report", State::Completed},
        {State::ObservedGone, "report", State::Completed},
        {State::Active, "report", State::Active},
        {State::NotOffered, "report", State::NotOffered},
        {State::Completed, "accept", State::Completed},
    };
    for (const Probe& p : probes) {
        State to = p.from;
        q.next(p.from, p.event, to);
        if (to != p.to) add("STATE_TABLE", std::string(stateName(p.from)) + " + " + p.event + " gives " + stateName(to) + ", want " + stateName(p.to));
    }

    // 11. a "gone" line states no cause and implies no actor
    for (const StringRow& r : rows) {
        std::string low = lower(r.text);
        bool goneLine = r.key.find("gone") != std::string::npos ||
                        (r.speaker == q.giverNpc && low.find("gone") != std::string::npos);
        if (!goneLine) continue;
        for (const char* w : kCauseWords)
            if (low.find(w) != std::string::npos) { add("CAUSE_WORD", r.key + " '" + w + "'"); break; }
    }
    return is;
}

// ---- engine ----------------------------------------------------------------------------------
Engine::Engine(const QuestData& data, const map::FloorMap& map) : q_(data), m_(map) {}

std::string Engine::nodeName(const std::string& id) const {
    const map::Node* n = m_.node(id);
    return n ? n->name : id;
}

Record Engine::record(const std::string& character) const {
    std::map<std::string, Record>::const_iterator it = records_.find(character);
    return it == records_.end() ? Record() : it->second;
}

namespace {
Step fatalStep(const char* code, const std::string& detail, State st) {
    Step s;
    s.fatal = true;
    s.code = code;
    s.detail = detail;
    s.before = s.after = st;
    return s;
}
Step rejected(const char* code, State st) {
    Step s;
    s.code = code;
    s.before = s.after = st;
    return s;
}
bool badStage(int stage) { return stage < -2 || stage > 2; }
}  // namespace

bool Engine::addLine(Step& s, const char* kind, const std::string& key, int stage,
                     const std::map<std::string, std::string>& values) {
    Issue e;
    std::string text;
    if (!fillLine(q_.strings, key, stage, values, text, e)) {
        s.fatal = true;
        s.ok = false;
        s.code = e.code;
        s.detail = e.detail;
        s.lines.clear();
        return false;
    }
    Line l;
    l.kind = kind;
    l.key = key;
    l.text = text;
    s.lines.push_back(l);
    return true;
}

Step Engine::offer(const std::string& ch, int stage, const Context&) {
    Record r = record(ch);
    if (badStage(stage)) return fatalStep("STAGE_RANGE", std::to_string(stage), r.state);
    if (r.state != State::NotOffered && r.state != State::Declined) return rejected("NOT_OFFERABLE", r.state);
    std::map<std::string, std::vector<std::string> >::const_iterator g = q_.stringGroups.find("offer");
    std::string key;
    if (g != q_.stringGroups.end())
        for (const std::string& k : g->second)
            if (q_.strings.forStage(k, stage)) { key = k; break; }
    if (key.empty()) return fatalStep("NO_LINE", "offer at stage " + std::to_string(stage), r.state);
    Step s;
    s.before = s.after = r.state;
    if (!addLine(s, "figure", key, stage, std::map<std::string, std::string>())) return s;
    if (key == kRefusedKey) {
        s.refused = true;
        // A declined character keeps the earlier offer; only a character with no offer is marked refused.
        if (r.state == State::NotOffered) { r.refused = true; r.offered = false; }
    } else {
        r.offered = true;
        r.refused = false;
    }
    s.ok = true;
    records_[ch] = r;
    return s;
}

Step Engine::decide(const std::string& ch, int stage, const Context& ctx, bool accepting) {
    Record r = record(ch);
    if (badStage(stage)) return fatalStep("STAGE_RANGE", std::to_string(stage), r.state);
    State to = r.state;
    if (!q_.next(r.state, accepting ? "accept" : "decline", to)) return rejected("NO_TRANSITION", r.state);
    // A NEW offer at -2 is refused, so there is nothing to accept or decline. Once the quest has
    // been offered at a higher standing, accept and decline still work at -2.
    if (r.state == State::NotOffered && (r.refused || (!r.offered && stage == -2))) return rejected("REFUSED", r.state);
    std::map<std::string, std::string> v;
    v["node_name"] = nodeName(q_.destNode);
    v["day"] = std::to_string(ctx.day);
    Step s;
    s.before = r.state;
    if (!addLine(s, "figure", accepting ? "fig_accept_ack" : "fig_decline_reply", stage, v)) return s;
    if (accepting && !addLine(s, "log", "log_quest_accepted", stage, v)) return s;
    r.state = to;
    s.after = to;
    s.ok = true;
    records_[ch] = r;
    return s;
}

Step Engine::accept(const std::string& ch, int stage, const Context& ctx) { return decide(ch, stage, ctx, true); }
Step Engine::decline(const std::string& ch, int stage, const Context& ctx) { return decide(ch, stage, ctx, false); }

Step Engine::arrive(const std::string& ch, const std::string& node, const std::string& chain, const Context& ctx) {
    Record r = record(ch);
    if (!m_.node(node)) return fatalStep("UNKNOWN_NODE", node, r.state);
    std::string value = chain.empty() ? q_.chainDefault : chain;
    if (!contains(q_.chainValues, value)) return fatalStep("BAD_CHAIN", value, r.state);
    if (r.state != State::Active || node != q_.destNode) return rejected("NOT_OBSERVING", r.state);
    State to = r.state;
    if (!q_.next(r.state, "arrive_" + q_.destNode + "_chain_" + value, to)) return rejected("NO_TRANSITION", r.state);
    std::map<std::string, std::string> v;
    v["node_name"] = nodeName(q_.destNode);
    v["day"] = std::to_string(ctx.day);
    Step s;
    s.before = r.state;
    if (!addLine(s, "narration", "lift_arrival_" + value, 0, v)) return s;
    if (!addLine(s, "log", "log_lift_observed_" + value, 0, v)) return s;
    r.state = to;
    r.chain = value;
    s.after = to;
    s.ok = true;
    records_[ch] = r;
    return s;
}

Step Engine::report(const std::string& ch, const std::string& node, int stage, const Context& ctx, RewardSource& source) {
    Record r = record(ch);
    if (!m_.node(node)) return fatalStep("UNKNOWN_NODE", node, r.state);
    if (badStage(stage)) return fatalStep("STAGE_RANGE", std::to_string(stage), r.state);
    if (node != q_.giverNode) return rejected("WRONG_NODE", r.state);
    std::map<std::string, std::string> v;
    v["node_name"] = nodeName(q_.destNode);
    v["day"] = std::to_string(ctx.day);
    Step s;
    s.before = s.after = r.state;
    s.ok = true;
    switch (r.state) {
        case State::NotOffered:
        case State::Declined:
            addLine(s, "figure", "fig_report_no_offer", stage, v);
            return s;
        case State::Active:
            addLine(s, "figure", "fig_report_not_yet", stage, v);
            return s;
        case State::Completed:
            addLine(s, "figure", "fig_repeat_done", stage, v);
            return s;
        default:
            break;
    }
    // Observed: pick the wording for the chain and the standing, roll the reward once, complete.
    State to = r.state;
    if (!q_.next(r.state, "report", to)) return rejected("NO_TRANSITION", r.state);
    std::string key;
    std::map<std::string, std::vector<std::string> >::const_iterator g = q_.stringGroups.find("report");
    std::string prefix = "fig_report_" + r.chain + "_";
    if (g != q_.stringGroups.end())
        for (const std::string& k : g->second)
            if (k.compare(0, prefix.size(), prefix) == 0 && q_.strings.forStage(k, stage)) { key = k; break; }
    if (key.empty()) return fatalStep("NO_LINE", prefix + "* at stage " + std::to_string(stage), r.state);

    double x = source.roll();
    s.rewardRolled = true;
    if (!(x >= 0.0 && x < 1.0)) return fatalStep("ROLL_RANGE", "reward source returned a value outside 0..1", r.state);
    std::string item;
    if (reward_.itemChance > 0.0 && !reward_.items.empty() && x < reward_.itemChance) {
        std::size_t idx = static_cast<std::size_t>(x / reward_.itemChance * static_cast<double>(reward_.items.size()));
        if (idx >= reward_.items.size()) idx = reward_.items.size() - 1;
        item = reward_.items[idx];
    }
    const char* rewardKey = item.empty() ? "fig_reward_none" : "fig_reward_item";
    v["reward_item"] = item;
    v["reward_line"] = std::string("@") + rewardKey;
    if (!addLine(s, "figure", key, stage, v)) return s;
    if (!addLine(s, "log", "log_quest_done", stage, v)) return s;
    if (!addLine(s, "log", item.empty() ? "log_reward_none" : "log_reward_item", stage, v)) return s;
    r.state = to;
    r.rewardRolled = true;
    r.rewardItem = item;
    s.after = to;
    records_[ch] = r;
    return s;
}

// ---- save and restore ------------------------------------------------------------------------
std::string Engine::save() const {
    std::string o = "{\"version\":1,\"quest_id\":" + esc(q_.questId) + ",\"characters\":{";
    bool first = true;
    for (const auto& kv : records_) {
        const Record& r = kv.second;
        if (!first) o += ",";
        first = false;
        o += esc(kv.first) + ":{\"state\":" + esc(stateName(r.state)) + ",\"offered\":" + (r.offered ? "true" : "false") +
             ",\"refused\":" + (r.refused ? "true" : "false") + ",\"chain\":" + esc(r.chain) +
             ",\"reward_rolled\":" + (r.rewardRolled ? "true" : "false") + ",\"reward_item\":" + esc(r.rewardItem) + "}";
    }
    return o + "}}\n";
}

bool Engine::restore(const std::string& text, Issue& err) {
    json::Value root;
    json::Error je;
    if (!json::parse(text, root, je)) { err.code = je.code; err.detail = je.describe(); return false; }
    auto bad = [&err](const char* code, const std::string& d) { err.code = code; err.detail = d; return false; };
    if (!root.isObject()) return bad("SAVE_SCHEMA", "top level is not an object");
    for (const std::string& k : root.keys)
        if (k != "version" && k != "quest_id" && k != "characters") return bad("SAVE_UNKNOWN_FIELD", k);
    const json::Value* ver = root.find("version");
    if (!ver || !ver->isNumber() || !ver->isInteger || ver->integer != 1) return bad("SAVE_VERSION", "version must be 1");
    const json::Value* qid = root.find("quest_id");
    if (!qid || !qid->isString()) return bad("SAVE_SCHEMA", "quest_id missing");
    if (qid->string != q_.questId) return bad("SAVE_WRONG_QUEST", qid->string);
    const json::Value* chars = root.find("characters");
    if (!chars || !chars->isObject()) return bad("SAVE_SCHEMA", "characters missing");
    std::map<std::string, Record> fresh;
    for (std::size_t i = 0; i < chars->items.size(); ++i) {
        const std::string& id = chars->keys[i];
        const json::Value& o = chars->items[i];
        if (!o.isObject()) return bad("SAVE_SCHEMA", id + ": not an object");
        for (const std::string& k : o.keys)
            if (k != "state" && k != "offered" && k != "refused" && k != "chain" && k != "reward_rolled" && k != "reward_item")
                return bad("SAVE_UNKNOWN_FIELD", id + "." + k);
        const json::Value* st = o.find("state");
        const json::Value* of = o.find("offered");
        const json::Value* rf = o.find("refused");
        const json::Value* ch = o.find("chain");
        const json::Value* rr = o.find("reward_rolled");
        const json::Value* ri = o.find("reward_item");
        if (!st || !st->isString() || !of || !of->isBool() || !rf || !rf->isBool() || !ch || !ch->isString() || !rr ||
            !rr->isBool() || !ri || !ri->isString())
            return bad("SAVE_SCHEMA", id + ": missing or mistyped field");
        Record r;
        if (!stateFromName(st->string, r.state)) return bad("SAVE_BAD_STATE", id + " " + st->string);
        r.offered = of->boolean;
        r.refused = rf->boolean;
        r.chain = ch->string;
        r.rewardRolled = rr->boolean;
        r.rewardItem = ri->string;
        if (!r.chain.empty() && !contains(q_.chainValues, r.chain)) return bad("SAVE_INCONSISTENT", id + ": unknown chain value");
        bool observed = r.state == State::ObservedPresent || r.state == State::ObservedGone || r.state == State::Completed;
        if (observed && r.chain.empty()) return bad("SAVE_INCONSISTENT", id + ": " + st->string + " without a recorded observation");
        if (!observed && !r.chain.empty()) return bad("SAVE_INCONSISTENT", id + ": chain recorded before observation");
        if (r.state == State::ObservedPresent && r.chain != "present") return bad("SAVE_INCONSISTENT", id + ": state and chain disagree");
        if (r.state == State::ObservedGone && r.chain != "gone") return bad("SAVE_INCONSISTENT", id + ": state and chain disagree");
        if ((r.state == State::Completed) != r.rewardRolled) return bad("SAVE_INCONSISTENT", id + ": reward_rolled must be true exactly when completed");
        if (!r.rewardItem.empty() && r.state != State::Completed) return bad("SAVE_INCONSISTENT", id + ": reward before completion");
        if (r.refused && (r.state != State::NotOffered || r.offered)) return bad("SAVE_INCONSISTENT", id + ": refused flag");
        fresh[id] = r;
    }
    records_.swap(fresh);
    return true;
}

